<?php
namespace axenox\BDT\Tests\PHPUnit;

use Composer\Autoload\ClassLoader;
use PHPUnit\Framework\TestCase;

// Generated by GitHub Copilot - Nov-10-2026
/**
 * Verifies extension discovery without the test bootstrap's namespace override.
 */
class ComposerAutoloadTest extends TestCase
{
    /**
     * Resolves Behat extensions using only the package's declared PSR-4 mapping.
     */
    public function testBehatExtensionsResolveFromPackageAutoloadMapping(): void
    {
        $packageRoot = dirname(__DIR__, 2);
        $manifest = json_decode(
            file_get_contents($packageRoot . DIRECTORY_SEPARATOR . 'composer.json'),
            true,
            512,
            JSON_THROW_ON_ERROR
        );
        $loader = new ClassLoader();
        foreach ($manifest['autoload']['psr-4'] as $prefix => $path) {
            $loader->addPsr4($prefix, $packageRoot . DIRECTORY_SEPARATOR . $path);
        }

        foreach ([
            'axenox\\BDT\\Behat\\Extension\\BehatExceptionExtension',
            'axenox\\BDT\\Behat\\TwigFormatter\\BehatFormatterExtension',
            'axenox\\BDT\\Behat\\DatabaseFormatter\\DatabaseFormatterExtension',
        ] as $class) {
            self::assertNotFalse($loader->findFile($class), $class . ' must be discoverable by Composer.');
        }
    }
}
